    private UiFontData() {
    }

    /** Rejoins the chunked row data at class initialisation. */
    private static String join(String[] parts) {
        StringBuilder out = new StringBuilder();
        for (String part : parts) {
            out.append(part);
        }
        return out.toString();
    }

